  "dataModelSchema": {
    "card": {
      "title": {
        "type": "string",
        "description": "当前等位店铺或等位服务标题",
        "sampleValue": "翠湖小馆"
      }
    },
    "queue": {
      "currentNumber": {
        "type": "string",
        "description": "当前已叫到的等位号码",
        "sampleValue": "A28"
      },
      "progressValue": {
        "type": "number",
        "description": "当前已叫号进度值",
        "sampleValue": 28
      },
      "progressTotal": {
        "type": "number",
        "description": "本轮等位总进度值",
        "sampleValue": 36
      },
      "ratioText": {
        "type": "string",
        "description": "已叫号与本轮总号数的比例展示文本",
        "sampleValue": "28/36"
      },
      "statusText": {
        "type": "string",
        "description": "叫号状态短文本",
        "sampleValue": "已到号"
      }
    },
    "action": {
      "label": {
        "type": "string",
        "description": "跳转查看店铺或等位详情的动作短文本",
        "sampleValue": "进店查看"
      }
    }
  },
  "assetCandidates": []
}

